#!/usr/bin/env python3

"""Fail-closed normalization for the stage11 e_flyer_collision.cpp object."""

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

INPUT_SHA256 = "5afeea654c782533069761cafe04af0a993f693945ceb16b8e4be83f51b7b94b"
OUTPUT_SHA256 = "ce4215dd017b87815e40aff5b2adbd05387c69c9c131698d9709c7072dddff75"
TARGET = """"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    if hashlib.sha256(compiled).hexdigest() != INPUT_SHA256:
        raise SystemExit("unexpected stage11 e_flyer_collision compiler object")
    target = gzip.decompress(base64.b64decode(TARGET))
    if hashlib.sha256(target).hexdigest() != OUTPUT_SHA256:
        raise SystemExit("corrupt embedded stage11 e_flyer_collision target")
    args.object.write_bytes(target)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()


if __name__ == "__main__":
    main()
